readonly record struct Ratio(int P, int Q) : IComparable<Ratio>
{
    public int CompareTo(Ratio other) => (P * other.Q).CompareTo(other.P * Q);
    public override string ToString()
    {
        int a = P, b = Q;
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return $"{P / a}/{Q / a}";
    }
}
